":"Projected gross margin","metric":"gross_margin_pct","good_direction":"up"},{"key":"fade","label":"Margin fade vs bid","metric":"margin_fade_pct","good_direction":"up"},{"key":"wip","label":"Over/under billing","metric":"over_under_billing_cents","good_direction":"up"},{"key":"co_exposure","label":"Pending change exposure","metric":"pending_change_exposure_cents","good_direction":"down"},{"key":"rfi_age","label":"RFI days open","metric":"rfi_avg_days_open","good_direction":"down"},{"key":"retainage","label":"Retainage receivable","metric":"retainage_receivable_cents","good_direction":"down"},{"key":"compliance","label":"Expired COIs and waivers","metric":"compliance_expired_count","good_direction":"down"},{"key":"backlog","label":"Backlog","metric":"backlog_cents","good_direction":"up"}],"books_proposal":{"cost_type_roles":{"LABOR":"DIRECT_LABOR_COST","MATERIALS":"MATERIALS_COST","SUBCONTRACTOR":"SUBCONTRACT_COST","EQUIPMENT":"EQUIPMENT_COST","OTHER":"OTHER_JOB_COST"},"rev_rec_by_job_type":{"lump_sum":"PCT_COSTS_INCURRED","gmp_cost_plus":"PCT_COSTS_INCURRED","tenant_improvement":"PCT_COSTS_INCURRED","small_work":"AS_BILLED"}},"sample_job":null,"plan_hash":"1b8545d5b7df397527e760951bc5af0d16563b485ee8df9930a8d9595df715e7"}$plan$::jsonb;
  v_admin       text;     -- Clerk user id of the company_admin we run as (never printed)
  v_admin_emp   uuid;
  v_admin_label text;
  v_tech        uuid;     -- an existing active core.employees row used as the field tech / installer
  v_tech_label  text;
  v_pack        text;
  v_install     uuid;
  v_applied     boolean := false;
  v_job uuid; v_key text; v_est uuid; v_est2 uuid; v_j jsonb; v_budget uuid; v_sov uuid; v_bill uuid;
  v_cmt uuid; v_cmt2 uuid; v_doc uuid; v_co uuid; v_wo uuid; v_wo2 uuid; v_res jsonb; v_sel uuid; v_sel2 uuid;
  v_opt uuid; v_item uuid; v_meas uuid; v_asset uuid; v_agr uuid; v_card uuid; v_card2 uuid; v_stock uuid;
  v_fail text[]; v_n int; v_amt bigint;
  v_thu date := current_date + ((10 - extract(isodow from current_date)::int) % 7) + 1;   -- next Thursday (1–7 days out)
  v_tue date := current_date + ((8 - extract(isodow from current_date)::int) % 7) + 1;    -- next Tuesday (1–7 days out)
  v_period_end date := case when extract(day from current_date) <= 25
                            then date_trunc('month', current_date)::date + 24
                            else (date_trunc('month', current_date) + interval '1 month')::date + 24 end;  -- pay-app cutoff (25th)
  n_jobs int := 0; n_cust int := 0; n_vend int := 0;
  v_c_riverside uuid;
  v_c_amesccu uuid;
  v_c_prairievet uuid;
  v_c_library uuid;
  v_c_ankenymed uuid;
  v_v_hawkeye uuid;
  v_v_raccoon uuid;
  v_v_capmech uuid;
  v_v_dmdoor uuid;

begin
  -- ---- 0. who we run as (read-only lookups as the migration owner; nothing is written here) ----
  select e.clerk_user_id, e.id, e.role || ' ' || e.first_name || ' ' || e.last_name
    into v_admin, v_admin_emp, v_admin_label
    from core.employees e
   where e.org_id = c_org and e.role = 'company_admin' and e.is_active and e.clerk_user_id is not null
   order by e.created_at, e.id limit 1;
  if v_admin is null then
    raise exception 'DEMO: org % has no active company_admin with a Clerk user id; nothing seeded', c_org;
  end if;
  -- field tech: an existing active employee other than the admin (Core owns employees; never inserted here)
  select e.id, e.role || ' ' || e.first_name || ' ' || e.last_name into v_tech, v_tech_label
    from core.employees e
   where e.org_id = c_org and e.is_active and e.id <> v_admin_emp
   order by (lower(e.first_name || ' ' || e.last_name) ~ '(install|tech|service)') desc, e.created_at, e.id limit 1;
  if v_tech is null then v_tech := v_admin_emp; v_tech_label := v_admin_label || ' (only employee)'; end if;
  -- existing demo parties (reused by name so a rerun calls no RPC and writes no activity)
  select c.id into v_c_riverside from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Riverside Dental Group')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_amesccu from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Ames Community Credit Union')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_prairievet from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Prairie Ridge Veterinary Clinic')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_library from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Story County Library Board')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_ankenymed from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Ankeny Medical Partners')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select v.id into v_v_hawkeye from core.vendors v
   where v.org_id = c_org and v.deleted_at is null and lower(regexp_replace(btrim(v.name), '\s+', ' ', 'g')) = lower('Demo — Hawkeye Drywall & Acoustics')
   order by v.is_active desc, v.created_at, v.id limit 1;
  select v.id into v_v_raccoon from core.vendors v
   where v.org_id = c_org and v.deleted_at is null and lower(regexp_replace(btrim(v.name), '\s+', ' ', 'g')) = lower('Demo — Raccoon River Electric')
   order by v.is_active desc, v.created_at, v.id limit 1;
  select v.id into v_v_capmech from core.vendors v
   where v.org_id = c_org and v.deleted_at is null and lower(regexp_replace(btrim(v.name), '\s+', ' ', 'g')) = lower('Demo — Capitol Mechanical')
   order by v.is_active desc, v.created_at, v.id limit 1;
  select v.id into v_v_dmdoor from core.vendors v
   where v.org_id = c_org and v.deleted_at is null and lower(regexp_replace(btrim(v.name), '\s+', ' ', 'g')) = lower('Demo — Des Moines Door & Hardware')
   order by v.is_active desc, v.created_at, v.id limit 1;

  -- ---- 1. become the company_admin ----
  perform set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  set local role authenticated;
  if public.get_org_id() is distinct from c_org then
    raise exception 'DEMO: the company_admin does not resolve to org % (active in more than one org?)', c_org;
  end if;

  -- ---- 2. pack ----
  select i.pack_key into v_pack from pm.pack_installs i
   where i.location_id = c_loc and i.role = 'primary' and i.status = 'ACTIVE';
  if v_pack is null then
    v_install := pm.apply_pack_plan(v_plan, 'primary');
    v_applied := true;
  elsif v_pack <> c_pack then
    raise exception 'DEMO: NWC already runs primary pack % (expected %); not seeding over it', v_pack, c_pack;
  end if;

  -- ---- 3. customers and vendors (shared master via pm.create_customer / pm.create_vendor) ----
  if v_c_riverside is null then
    v_c_riverside := pm.create_customer('Demo — Riverside Dental Group', 'facilities@riverside-dental.example', '515-555-0141', c_loc, 'Dana', 'Whitcomb');
    n_cust := n_cust + 1;
  end if;
  if v_c_amesccu is null then
    v_c_amesccu := pm.create_customer('Demo — Ames Community Credit Union', 'facilities@ames-ccu.example', '515-555-0152', c_loc, 'Greg', 'Halvorsen');
    n_cust := n_cust + 1;
  end if;
