    v_c_prairievet := pm.create_customer('Demo — Prairie Ridge Veterinary Clinic', 'office@prairieridgevet.example', '515-555-0163', c_loc, 'Jenna', 'Ostrander');
    n_cust := n_cust + 1;
  end if;
  if v_c_library is null then
    v_c_library := pm.create_customer('Demo — Story County Library Board', 'director@storycountylibrary.example', '515-555-0174', c_loc, 'Paul', 'Lindquist');
    n_cust := n_cust + 1;
  end if;
  if v_c_ankenymed is null then
    v_c_ankenymed := pm.create_customer('Demo — Ankeny Medical Partners', 'realestate@ankenymed.example', '515-555-0185', c_loc, 'Priya', 'Raman');
    n_cust := n_cust + 1;
  end if;
  if v_v_hawkeye is null then
    v_v_hawkeye := pm.create_vendor('Demo — Hawkeye Drywall & Acoustics', 'estimating@hawkeyedrywall.example', '515-555-0211', 'SUBCONTRACTOR', c_loc);
    n_vend := n_vend + 1;
  end if;
  if v_v_raccoon is null then
    v_v_raccoon := pm.create_vendor('Demo — Raccoon River Electric', 'bids@raccoonriverelectric.example', '515-555-0222', 'SUBCONTRACTOR', c_loc);
    n_vend := n_vend + 1;
  end if;
  if v_v_capmech is null then
    v_v_capmech := pm.create_vendor('Demo — Capitol Mechanical', 'service@capitolmech.example', '515-555-0233', 'SUBCONTRACTOR', c_loc);
    n_vend := n_vend + 1;
  end if;
  if v_v_dmdoor is null then
    v_v_dmdoor := pm.create_vendor('Demo — Des Moines Door & Hardware', 'orders@dmdoor.example', '515-555-0244', 'SUPPLIER', c_loc);
    n_vend := n_vend + 1;
  end if;

  -- ---- 4. company setup ----

  if not exists (select 1 from pm.labor_settings s where s.location_id = c_loc) then
    perform pm.set_labor_settings(c_loc, 0.32, 0.18, 'Demo: payroll burden (FICA, FUTA/SUTA, workers comp, health) and estimating overhead');
  end if;
  select c.id into v_card from pm.labor_rate_cards c where c.location_id = c_loc and c.key = 'carpenter';
  if v_card is null then
    v_card := pm.save_labor_rate_card(c_loc, 'carpenter', 'Carpenter (self-perform)', 3400, null, null, 7200, null);
  end if;
  select c.id into v_card2 from pm.labor_rate_cards c where c.location_id = c_loc and c.key = 'superintendent';
  if v_card2 is null then
    v_card2 := pm.save_labor_rate_card(c_loc, 'superintendent', 'Superintendent', 4600, null, null, 9800, null);
  end if;
  if v_tech <> v_admin_emp and not exists (select 1 from pm.employee_rate_cards e where e.employee_id = v_tech and e.location_id = c_loc) then
    perform pm.set_employee_rate_card(v_tech, c_loc, v_card);
  end if;

  -- ---- 5. jobs ----

  -- ------------------------------------------------------------------------
  -- nwc-ti-riverside-dental: REAL — TI mid-construction, Pay Application #1 drafted for the 25th
  -- ------------------------------------------------------------------------
  v_key := 'nwc-ti-riverside-dental';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'tenant_improvement', 'Riverside Dental Group — Suite 140 tenant improvement', v_c_riverside, null, false,
      jsonb_build_object('_demo', v_key, 'market_sector', 'healthcare', 'building_sf', 6850, 'permit_number', 'BLD-2026-04417',
                         'architect', 'Slate Line Architecture (demo)', 'prevailing_wage', false, 'customer_reference', 'RDG PO 2026-118'));
    update pm.projects set site_address_line1 = '4110 NW Urbandale Dr, Suite 140', site_city = 'Urbandale', site_state = 'IA', site_zip = '50322',
           planned_start = current_date + -38, planned_finish = current_date + 41,
           pm_user_id = v_admin
     where job_id = v_job;
    insert into pm.estimates (job_id, title, retainage_pct, valid_until, notes)
      values (v_job, 'Base bid — Suite 140 dental TI (drawings A1.0–A6.2 rev 2)', 0.1, current_date - 30, 'Excludes dental equipment and casework (by owner). Retainage 10% per AIA A101.') returning id into v_est;
    insert into pm.estimate_lines (estimate_id, line_no, sort, cost_code_id, description, qty, uom, unit_cost_cents, unit_price_cents, cost_cents, amount_cents, is_allowance)
    select v_est, x.n, x.n, c.id, x.d, x.qty::numeric, x.uom, x.uc::bigint, x.up::bigint, x.cost::bigint, x.amt::bigint, x.allow
      from (values
      (1, '01 31 00', 'Project management and general conditions', 1, 'LS', 2850000, 3420000, 2850000, 3420000, false),
      (2, '01 50 00', 'Temporary facilities, protection and dust control', 1, 'LS', 620000, 740000, 620000, 740000, false),
      (3, '02 41 00', 'Selective demolition (former retail suite)', 1, 'LS', 1840000, 2210000, 1840000, 2210000, false),
      (4, '06 10 00', 'Rough carpentry and in-wall blocking (self-perform)', 1, 'LS', 980000, 1190000, 980000, 1190000, false),
      (5, '08 11 00', 'Hollow-metal frames, wood doors and hardware', 1, 'LS', 3160000, 3780000, 3160000, 3780000, false),
      (6, '09 21 16', 'Metal stud framing and gypsum board', 1, 'LS', 7250000, 8690000, 7250000, 8690000, false),
      (7, '09 51 00', 'Acoustical ceilings', 1, 'LS', 1930000, 2320000, 1930000, 2320000, false),
      (8, '09 65 00', 'Resilient flooring and rubber base', 1, 'LS', 1690000, 2030000, 1690000, 2030000, false),
      (9, '09 91 00', 'Painting and wall protection', 1, 'LS', 1120000, 1350000, 1120000, 1350000, false),
      (10, '22 00 00', 'Plumbing incl. dental vacuum and compressed air', 1, 'LS', 5480000, 6540000, 5480000, 6540000, false),
      (11, '23 00 00', 'HVAC: RTU tie-in, VAV boxes and ductwork', 1, 'LS', 6190000, 7380000, 6190000, 7380000, false),
      (12, '26 00 00', 'Electrical, lighting and low voltage', 1, 'LS', 5870000, 7010000, 5870000, 7010000, false),
      (13, '01 21 16', 'Contingency (owner-controlled)', 1, 'LS', 1600000, 1990000, 1600000, 1990000, false)) x(n, code, d, qty, uom, uc, up, cost, amt, allow)
      left join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 13 or exists (select 1 from pm.estimate_lines l where l.estimate_id = v_est and l.cost_code_id is null and l.cost_cents <> 0) then
      raise exception 'DEMO %: estimate lines did not resolve their cost codes', v_key;
    end if;
    perform pm.send_estimate(v_est);
    v_j := pm.accept_estimate(v_est);      -- ORIGINAL budget by cost code + PRIME contract 48650000 cents at 10% retainage
    v_fail := pm.transition_stage(v_job, 'awarded');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'awarded', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'preconstruction');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'preconstruction', v_fail; end if;
    -- subcontracts + PO (DRAFT: approval needs a second person, preparer != approver)
    insert into pm.commitments (job_id, vendor_id, commitment_type, title, description, retainage_pct)
      values (v_job, v_v_hawkeye, 'SUBCONTRACT', 'Framing, drywall and acoustical ceilings', 'Per Section 09 21 16 and 09 51 00; includes in-wall blocking coordination with Northwind carpentry.', 0.1) returning id into v_cmt;
    insert into pm.commitment_lines (commitment_id, line_no, cost_code_id, description, amount_cents)
    select v_cmt, x.n, c.id, x.d, x.a::bigint
      from (values
      (1, '09 21 16', 'Metal stud framing, gypsum board, level 4 finish', 6890000),
      (2, '09 51 00', 'ACT grid and 2x2 tile, operatory clean-room tile', 1840000)) x(n, code, d, a)
      join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 2 then raise exception 'DEMO %: commitment lines matched % of 2 cost codes', v_key, v_n; end if;
    insert into pm.compliance_docs (commitment_id, doc_type, status, required, notes)
      values (v_cmt, 'COI', 'RECEIVED', true, 'ACORD 25: GL $1M/$2M, auto $1M, umbrella $5M; Northwind and owner additional insured')
      returning id into v_doc;
    perform pm.verify_compliance_doc(v_doc, current_date + 12);          -- expiring soon
    insert into pm.compliance_docs (commitment_id, doc_type, status, required, covers_through, amount_cents, notes)
