    insert into pm.commitment_lines (commitment_id, line_no, cost_code_id, description, amount_cents)
    select v_cmt, x.n, c.id, x.d, x.a::bigint
      from (values
      (1, '08 11 00', '(14) HM frames, (14) solid-core birch doors, hardware sets HW-1 to HW-4', 2795000)) x(n, code, d, a)
      join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 1 then raise exception 'DEMO %: commitment lines matched % of 1 cost codes', v_key, v_n; end if;
    v_fail := pm.transition_stage(v_job, 'construction');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'construction', v_fail; end if;
    -- a waiver still owed for Pay App #1
    insert into pm.compliance_docs (commitment_id, doc_type, status, required, notes)
      values (v_cmt2, 'LIEN_WAIVER_CONDITIONAL', 'MISSING', true, 'Needed with Pay Application #1');
    -- schedule of values (lines = the accepted bid) + Pay Application #1
    insert into pm.sov_versions (job_id, contract_id, memo)
      values (v_job, (v_j ->> 'contract_id')::uuid, 'Original schedule of values per executed AIA A101/A201') returning id into v_sov;
    insert into pm.sov_lines (sov_version_id, line_no, cost_code_id, description, scheduled_value_cents, sort)
    select v_sov, l.line_no, l.cost_code_id, l.description, l.amount_cents, l.sort from pm.estimate_lines l where l.estimate_id = v_est;
    perform pm.activate_sov_version(v_sov);
    v_bill := pm.generate_sov_billing(v_job, v_sov, v_period_end, (
      select jsonb_agg(jsonb_build_object('sov_line_id', s.id, 'pct_complete', x.pct, 'stored_materials_cents', x.stored) order by s.line_no)
        from pm.sov_lines s
        join (values (1, 0.45, 0), (2, 0.6, 0), (3, 1, 0), (4, 0.8, 0), (5, 0.1, 1240000), (6, 0.65, 0), (7, 0, 0), (8, 0, 0), (9, 0, 0), (10, 0.55, 0), (11, 0.5, 0), (12, 0.5, 0), (13, 0, 0)) x(n, pct, stored) on x.n = s.line_no
       where s.sov_version_id = v_sov));
    perform pm.set_progress(v_job, 0.42);
    insert into pm.change_orders (job_id, contract_id, title, description, reason, amount_cents, cost_impact_cents, schedule_days)
      values (v_job, pm.primary_contract_id(c_org, v_job), 'Add (2) sterilization-room sinks (RFI-014)', 'Owner requested a second sink at sterilization and a hand sink at lab; adds 2 fixtures, waste/vent, and casework cutouts.', 'OWNER_REQUEST', 864000, 690000, 2)
