      values (v_job, pm.primary_contract_id(c_org, v_job), 'Upgrade corridor doors to 20-minute rated (plan review comment)', 'City of Urbandale plan review requires 20-min rated corridor doors with closers at 6 openings.', 'CODE', 1425000, 1180000, 0)
      returning id into v_co;
