      from (values
      (1, 'Preconstruction meeting with owner and architect', 'DONE', false, -6, -6, 1, 'admin'),
      (2, 'Issue subcontracts: sitework, concrete, steel', 'IN_PROGRESS', false, -4, 5, 0.4, 'admin'),
      (3, 'Submittals: steel, storefront, RTUs', 'IN_PROGRESS', false, -2, 12, 0.2, null),
      (4, 'Building permit (City of Ames)', 'IN_PROGRESS', false, -10, 9, 0.7, null),
      (5, 'Builder''s risk certificate from owner', 'BLOCKED', false, -3, 4, null, null),
      (6, 'Notice to proceed', 'TODO', true, 18, 18, null, null),
      (7, 'Mobilize, erosion control, mass grading', 'TODO', false, 21, 35, null, null)) x(n, t, st, ms, s, d, pct, who);
    n_jobs := n_jobs + 1;
  end if;

  -- ------------------------------------------------------------------------
  -- nwc-closeout-prairie-ridge-vet: REAL — closeout, final billing drafted
  -- ------------------------------------------------------------------------
  v_key := 'nwc-closeout-prairie-ridge-vet';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'tenant_improvement', 'Prairie Ridge Veterinary Clinic — exam wing remodel', v_c_prairievet, null, false,
      jsonb_build_object('_demo', v_key, 'market_sector', 'healthcare', 'building_sf', 3100, 'permit_number', 'BLD-2026-01882'));
    update pm.projects set site_address_line1 = '8805 Hickman Rd', site_city = 'Clive', site_state = 'IA', site_zip = '50325',
           planned_start = current_date + -126, planned_finish = current_date + -9,
           pm_user_id = v_admin
     where job_id = v_job;
    insert into pm.budgets (job_id, kind, version, status, label, as_of) values (v_job, 'ORIGINAL', 1, 'APPROVED', 'Original budget', current_date)
      returning id into v_budget;
    insert into pm.budget_lines (budget_id, cost_code_id, description, amount_cents, sort)
    select v_budget, c.id, x.d, x.a::bigint, x.s
      from (values
      ('01 31 00', 'Project management', 1800000, 1),
      ('01 31 13', 'Field supervision', 2200000, 2),
      ('02 41 00', 'Selective demolition', 1450000, 3),
      ('06 40 00', 'Exam room casework', 3100000, 4),
      ('08 11 00', 'Doors, frames and hardware', 1980000, 5),
      ('09 21 16', 'Framing and drywall', 4400000, 6),
      ('09 51 00', 'Acoustical ceilings', 1260000, 7),
      ('09 65 00', 'Seamless resilient flooring', 2140000, 8),
      ('09 91 00', 'Painting', 980000, 9),
      ('22 00 00', 'Plumbing (exam sinks, tub table)', 3850000, 10),
      ('23 00 00', 'HVAC (exhaust, kennel air changes)', 2980000, 11),
      ('26 00 00', 'Electrical', 3460000, 12)) x(code, d, a, s)
      join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 12 then raise exception 'DEMO %: budget matched % of 12 cost codes', v_key, v_n; end if;
    perform pm.set_contract(v_job, 33860000);
    insert into pm.compliance_docs (job_id, vendor_id, doc_type, status, required, notes)
      values (v_job, v_v_capmech, 'COI', 'RECEIVED', true, 'Capitol Mechanical — ACORD 25') returning id into v_doc;
    perform pm.verify_compliance_doc(v_doc, current_date + 150);
    v_fail := pm.transition_stage(v_job, 'awarded');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'awarded', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'preconstruction');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'preconstruction', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'construction');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'construction', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'substantial_completion');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'substantial_completion', v_fail; end if;
    insert into pm.punch_items (job_id, kind, title, area, status, due_on, closed_at, responsible_vendor_id)
    values (v_job, 'PUNCH', 'Touch-up paint at exam 3 door frame', 'Exam 3', 'CLOSED', current_date - 16, now() - interval '14 days', null),
           (v_job, 'PUNCH', 'Adjust closer at treatment room door', 'Treatment', 'CLOSED', current_date - 16, now() - interval '13 days', null),
           (v_job, 'PUNCH', 'Re-caulk tub table backsplash', 'Treatment', 'CLOSED', current_date - 15, now() - interval '12 days', v_v_capmech),
           (v_job, 'PUNCH', 'Replace cracked ceiling tile at corridor', 'Corridor', 'CLOSED', current_date - 15, now() - interval '12 days', null),
           (v_job, 'PUNCH', 'Label exhaust fan EF-2 and balance report', 'Kennel', 'CLOSED', current_date - 14, now() - interval '11 days', v_v_capmech),
           (v_job, 'PUNCH', 'Clean flooring and remove protection', 'All', 'CLOSED', current_date - 12, now() - interval '10 days', null),
           (v_job, 'PUNCH', 'Install missing outlet cover at exam 1', 'Exam 1', 'CLOSED', current_date - 12, now() - interval '10 days', null);
    insert into pm.punch_items (job_id, kind, title, area, status, due_on, description)
    values (v_job, 'WARRANTY', 'Kennel exhaust noisy at high speed', 'Kennel', 'OPEN', current_date + 7, 'Owner called after occupancy; Capitol Mechanical to check fan bearing (warranty).');
    v_fail := pm.transition_stage(v_job, 'closeout');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'closeout', v_fail; end if;
    perform pm.set_progress(v_job, 1.0);
    v_bill := pm.generate_progress_billing(v_job, current_date, 1.0);   -- final billing, retainage withheld until release
    insert into pm.tasks (job_id, title, status, is_milestone, start_on, due_on, duration_days, pct_complete, sort, completed_at, assignee_user_id, assignee_employee_id)
    select v_job, x.t, x.st, x.ms, current_date + x.s, current_date + x.d, x.d - x.s, x.pct::numeric, x.n,
           case when x.st = 'DONE' then now() end, case when x.who = 'admin' then v_admin end, case when x.who = 'tech' then v_tech end
      from (values
      (1, 'Substantial completion walk with owner', 'DONE', true, -12, -12, 1, 'admin'),
      (2, 'Punch list', 'DONE', false, -16, -10, 1, null),
      (3, 'Certificate of occupancy', 'DONE', true, -9, -9, 1, null),
      (4, 'O&M manuals, warranties and as-builts to owner', 'IN_PROGRESS', false, -8, 3, 0.6, 'admin'),
      (5, 'Final pay application and unconditional final waivers', 'IN_PROGRESS', false, -2, 5, 0.3, 'admin'),
      (6, 'Retainage release request', 'TODO', false, 10, 20, null, null)) x(n, t, st, ms, s, d, pct, who);
    insert into pm.field_logs (job_id, kind, log_date, body, weather, crew_count, hours, ext)
    select v_job, 'DAILY', w.d, x.body, jsonb_build_object('summary', x.wx, 'high_f', x.hi, 'low_f', x.lo), x.crew, x.crew * 8,
           jsonb_build_object('manpower', x.crew, 'weather', x.wx || ', ' || x.hi || '°F / ' || x.lo || '°F')
      from (select g::date as d, row_number() over (order by g desc) as rn
              from generate_series(current_date - 23, current_date - 10, interval '1 day') g
             where extract(isodow from g) < 6) w
      join (values
      (1, 'Final clean; owner moved in exam furniture; CO inspection passed.', 'Sunny', 66, 47, 4),
      (2, 'Punch walk with Dr. Ostrander: 7 items; Capitol Mechanical balancing kennel exhaust.', 'Cloudy', 62, 45, 6),
      (3, 'Seamless flooring cured; casework tops set; plumbing trim complete.', 'Light rain', 57, 46, 8)) x(rn, body, wx, hi, lo, crew) on x.rn = w.rn;
    n_jobs := n_jobs + 1;
  end if;

  -- ------------------------------------------------------------------------
  -- nwc-bid-library-roof: SAMPLE — bidding, bid sent (labor line priced from a rate card)
  -- ------------------------------------------------------------------------
  v_key := 'nwc-bid-library-roof';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'lump_sum', 'Story County Library — roof replacement and RTU upgrades', v_c_library, null, true,
      jsonb_build_object('_demo', v_key, 'market_sector', 'public', 'building_sf', 24800, 'prevailing_wage', true));
    update pm.projects set site_address_line1 = '515 Douglas Ave', site_city = 'Ames', site_state = 'IA', site_zip = '50010',
           planned_start = current_date + 45, planned_finish = current_date + 120,
           pm_user_id = v_admin
     where job_id = v_job;
    insert into pm.estimates (job_id, title, retainage_pct, valid_until, notes)
      values (v_job, 'Lump-sum bid — roof replacement and RTU upgrades', 0.05, current_date + 60, 'Alternate 1 (add walk pads) priced separately. Prevailing wage per owner requirements.') returning id into v_est;
    insert into pm.estimate_lines (estimate_id, line_no, sort, cost_code_id, description, qty, uom, unit_cost_cents, unit_price_cents, cost_cents, amount_cents, is_allowance)
    select v_est, x.n, x.n, c.id, x.d, x.qty::numeric, x.uom, x.uc::bigint, x.up::bigint, x.cost::bigint, x.amt::bigint, x.allow
      from (values
      (1, '01 50 00', 'Temporary facilities, roof protection and hoisting', 1, 'LS', 940000, 1180000, 940000, 1180000, false),
      (2, '02 41 00', 'Tear off existing built-up roof to deck', 1, 'LS', 3860000, 4690000, 3860000, 4690000, false),
      (3, '07 21 00', 'Tapered polyiso insulation, R-30 average', 1, 'LS', 5230000, 6350000, 5230000, 6350000, false),
      (4, '07 50 00', '60-mil TPO membrane, fully adhered (24,800 SF)', 1, 'LS', 14890000, 17960000, 14890000, 17960000, false),
      (5, '23 00 00', 'Replace (3) RTUs with curb adapters, crane pick', 1, 'LS', 18640000, 22480000, 18640000, 22480000, false),
      (6, '26 00 00', 'RTU disconnects and controls wiring', 1, 'LS', 2170000, 2630000, 2170000, 2630000, false),
      (7, '01 41 00', 'Building permit (City of Ames)', 1, 'LS', 420000, 420000, 420000, 420000, false)) x(n, code, d, qty, uom, uc, up, cost, amt, allow)
      left join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 7 or exists (select 1 from pm.estimate_lines l where l.estimate_id = v_est and l.cost_code_id is null and l.cost_cents <> 0) then
      raise exception 'DEMO %: estimate lines did not resolve their cost codes', v_key;
    end if;
    insert into pm.estimate_lines (estimate_id, line_no, sort, cost_code_id, description, labor_rate_card_id, labor_hours)
    select v_est, 8, 8, c.id, 'Superintendent, 12 weeks part-time', v_card2, 160
      from pm.cost_codes c where c.location_id = c_loc and c.job_id is null and c.code = '01 31 13';
    perform pm.send_estimate(v_est);
    insert into pm.tasks (job_id, title, status, is_milestone, start_on, due_on, duration_days, pct_complete, sort, completed_at, assignee_user_id, assignee_employee_id)
    select v_job, x.t, x.st, x.ms, current_date + x.s, current_date + x.d, x.d - x.s, x.pct::numeric, x.n,
           case when x.st = 'DONE' then now() end, case when x.who = 'admin' then v_admin end, case when x.who = 'tech' then v_tech end
      from (values
      (1, 'Pre-bid walkthrough with library facilities', 'DONE', false, -6, -6, 1, 'admin'),
      (2, 'RTU pricing from Capitol Mechanical', 'IN_PROGRESS', false, -5, 2, 0.5, null),
      (3, 'Sealed bid due 2:00 pm', 'TODO', true, 6, 6, null, 'admin')) x(n, t, st, ms, s, d, pct, who);
    n_jobs := n_jobs + 1;
  end if;

  -- ------------------------------------------------------------------------
  -- nwc-gmp-ankeny-mob: SAMPLE — awarded GMP, design development
  -- ------------------------------------------------------------------------
  v_key := 'nwc-gmp-ankeny-mob';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'gmp_cost_plus', 'Ankeny Medical Partners — medical office building (GMP)', v_c_ankenymed, null, true,
      jsonb_build_object('_demo', v_key, 'market_sector', 'healthcare', 'building_sf', 38000, 'architect', 'Prairie Forge Design (demo)'));
    update pm.projects set site_address_line1 = '2400 SW State St', site_city = 'Ankeny', site_state = 'IA', site_zip = '50023',
           planned_start = current_date + 60, planned_finish = current_date + 420,
           pm_user_id = v_admin
     where job_id = v_job;
    perform pm.set_contract(v_job, 485000000, 'PRIME', 0.05);
    v_fail := pm.transition_stage(v_job, 'awarded');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'awarded', v_fail; end if;
    insert into pm.tasks (job_id, title, status, is_milestone, start_on, due_on, duration_days, pct_complete, sort, completed_at, assignee_user_id, assignee_employee_id)
    select v_job, x.t, x.st, x.ms, current_date + x.s, current_date + x.d, x.d - x.s, x.pct::numeric, x.n,
           case when x.st = 'DONE' then now() end, case when x.who = 'admin' then v_admin end, case when x.who = 'tech' then v_tech end
      from (values
      (1, 'Execute AIA A133 and GMP amendment', 'DONE', true, -14, -7, 1, 'admin'),
      (2, 'Design development pricing update', 'IN_PROGRESS', false, -5, 9, 0.35, 'admin'),
      (3, 'Early release: sitework and foundations package', 'TODO', false, 10, 24, null, null)) x(n, t, st, ms, s, d, pct, who);
    n_jobs := n_jobs + 1;
  end if;

  -- ------------------------------------------------------------------------
  -- nwc-small-door-closer: SAMPLE — small T&M work in progress, time submitted
  -- ------------------------------------------------------------------------
  v_key := 'nwc-small-door-closer';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'small_work', 'Riverside Dental Group — after-hours door closer and panic bar repair', v_c_riverside, null, true,
      jsonb_build_object('_demo', v_key, 'customer_reference', 'Work request #77'));
    update pm.projects set site_address_line1 = '4110 NW Urbandale Dr', site_city = 'Urbandale', site_state = 'IA', site_zip = '50322',
           planned_start = current_date + -1, planned_finish = current_date + 1,
           pm_user_id = v_admin
     where job_id = v_job;
    v_fail := pm.transition_stage(v_job, 'scheduled');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'scheduled', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'in_progress');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'in_progress', v_fail; end if;
    insert into pm.time_entries (job_id, employee_id, work_date, hours, pay_type, cost_code_id, notes, approval_state, work_order_id)
    select v_job, v_tech, current_date + x.day, x.h::numeric, x.pay, c.id, x.notes, 'SUBMITTED', x.wo::uuid
      from (values
      (-1, 3, 'REG', '08 11 00', 'Replace failed closer at rear exit; adjust strike', null),
      (-1, 1.5, 'OT', '08 11 00', 'After hours: re-key panic bar trim (clinic closed at 6)', null)) x(day, h, pay, code, notes, wo)
      join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    n_jobs := n_jobs + 1;
  end if;


  -- ---- 6. summary ----
  raise notice 'DEMO NWC: ran as %; field tech %; pack % (%); this run created % job(s), % customer(s), % vendor(s)',
    v_admin_label, v_tech_label, c_pack, case when v_applied then 'applied now' else 'already installed' end, n_jobs, n_cust, n_vend;
  raise notice 'DEMO NWC totals: % demo jobs (% sample, % real); % tasks; % budget lines; % estimates (% accepted); % change orders; % commitments; % work orders (% dispatched); % billing requests; % deposit requests; % selections; % assets; % agreements; % time entries; % daily logs; % Books events from demo jobs',
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo' and p.is_sample),
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo' and not p.is_sample),
    (select count(*) from pm.tasks t join pm.projects p on p.job_id = t.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.budget_lines l join pm.budgets b on b.id = l.budget_id join pm.projects p on p.job_id = b.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.estimates e where e.location_id = c_loc),
    (select count(*) from pm.estimates e where e.location_id = c_loc and e.status = 'ACCEPTED'),
    (select count(*) from pm.change_orders x join pm.projects p on p.job_id = x.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.commitments x where x.location_id = c_loc),
    (select count(*) from pm.work_orders w where w.location_id = c_loc),
    (select count(distinct d.work_order_id) from pm.dispatch_assignments d join pm.work_orders w on w.id = d.work_order_id where w.location_id = c_loc and d.status <> 'CANCELLED'),
    (select count(*) from pm.billing_requests r where r.location_id = c_loc),
    (select count(*) from pm.deposit_requests r where r.location_id = c_loc),
    (select count(*) from pm.selections s join pm.projects p on p.job_id = s.job_id where p.location_id = c_loc),
    (select count(*) from pm.assets a where a.location_id = c_loc),
    (select count(*) from pm.service_agreements a where a.location_id = c_loc),
    (select count(*) from pm.time_entries t join pm.projects p on p.job_id = t.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.field_logs l join pm.projects p on p.job_id = l.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from core.events e where e.org_id = c_org and e.source_module = 'PROJECTS'
        and e.payload ->> 'job_id' in (select p.job_id::text from pm.projects p where p.location_id = c_loc and p.ext ? '_demo'));
end
$seed$;
